        ImageView logo=imagen("/com/tecnomant/assets/01_Logos/logo_horizontal_oscuro_2x.png",365,64);
        Label separador=Componentes.etiqueta("|", "text-muted");
        Label subtitulo=Componentes.etiqueta("Sistema de Gestión de Órdenes de Trabajo", "text-muted");
        Region espacio=new Region();HBox.setHgrow(espacio,Priority.ALWAYS);
        Label fecha=Componentes.etiqueta(LocalDate.now().format(FECHA_LARGA), "top-date");
        Label usuario=Componentes.etiqueta("Administrador\nSupervisor", "user-label");
        barra.getChildren().addAll(logo,separador,subtitulo,espacio,fecha,usuario);return barra;
