    /** Panel decorativo no interactivo: la imagen se instancia una vez desde el classpath. */
    private StackPane ciudadFuturista(VBox sidebar){
        StackPane panel=new StackPane();panel.getStyleClass().add("sidebar-city");panel.setMinHeight(205);panel.prefHeightProperty().bind(sidebar.heightProperty().multiply(.40));panel.setMouseTransparent(true);
        Image ciudad=new Image(getClass().getResource("/images/futuristic-city.png").toExternalForm(),true);Region fondo=new Region();fondo.setMaxSize(Double.MAX_VALUE,Double.MAX_VALUE);fondo.setBackground(new Background(new BackgroundImage(ciudad,BackgroundRepeat.NO_REPEAT,BackgroundRepeat.NO_REPEAT,BackgroundPosition.CENTER,new BackgroundSize(100,100,true,true,false,true))));
        Rectangle recorte=new Rectangle();recorte.widthProperty().bind(panel.widthProperty());recorte.heightProperty().bind(panel.heightProperty());panel.setClip(recorte);
        Region degradado=new Region();degradado.setMaxSize(Double.MAX_VALUE,Double.MAX_VALUE);degradado.getStyleClass().add("city-overlay");
        Label mensaje=Componentes.etiqueta("Mantenimiento que\nimpulsa tu industria", "city-message");Region acento=new Region();acento.getStyleClass().add("city-accent");acento.setPrefSize(42,3);VBox texto=new VBox(10,mensaje,acento);texto.getStyleClass().add("city-copy");
        panel.getChildren().addAll(fondo,degradado,texto);StackPane.setAlignment(texto,Pos.BOTTOM_LEFT);StackPane.setMargin(texto,new Insets(0,0,20,18));return panel;
    }
    private Button nav(String texto,String icono,Runnable accion){Button b=new Button(texto);ImageView i=Componentes.icono(icono,21);if(i!=null)b.setGraphic(i);b.setMaxWidth(Double.MAX_VALUE);b.getStyleClass().add("nav-button");b.setOnAction(e->accion.run());return b;}
    private void activo(Button actual){quitarActivo(inicio);quitarActivo(ordenes);quitarActivo(nueva);quitarActivo(editar);quitarActivo(estructura);quitarActivo(pruebas);actual.getStyleClass().add("nav-active");}
    private void quitarActivo(Button boton){boton.getStyleClass().remove("nav-active");}
    private void cambiar(Node vista){contenido.getChildren().setAll(vista);}
    private void mostrarDashboard(boolean modoInicio) {
        activo(modoInicio?inicio:ordenes);controller.refrescar();
        VBox page=pagina(modoInicio?"Dashboard":"Órdenes de trabajo",modoInicio?"Resumen general de órdenes de trabajo":"Consulta y gestión de órdenes de trabajo");
        if(modoInicio)page.getChildren().add(tarjetasEstadisticas());
        HBox acciones=new HBox(10);TextField buscar=new TextField();buscar.setPromptText("Buscar por código o cliente...");buscar.setPrefWidth(430);HBox.setHgrow(buscar,Priority.ALWAYS);
        Button bNueva=Componentes.boton("＋ Nueva orden","button-primary"),bEditar=Componentes.boton("✎ Editar","button-outline"),bEliminar=Componentes.boton("⌫ Eliminar","button-danger"),bDemo=Componentes.boton("Cargar ejemplos","button-outline");
        acciones.getChildren().addAll(buscar,bNueva,bEditar,bEliminar,bDemo);page.getChildren().add(acciones);
        tabla=crearTabla();detalle=Componentes.etiqueta("Seleccione una orden para ver su detalle.","detail-text");
        VBox panelTabla=Componentes.tarjeta();Label t=Componentes.etiqueta("Órdenes de trabajo", "section-title");panelTabla.getChildren().addAll(t,tabla,navegacionTabla());VBox.setVgrow(tabla,Priority.ALWAYS);
        VBox panelDetalle=Componentes.tarjeta();panelDetalle.setPrefWidth(280);panelDetalle.getChildren().addAll(Componentes.etiqueta("Detalle de la orden","section-title"),detalle);
        HBox cuerpo=new HBox(16,panelTabla,panelDetalle);HBox.setHgrow(panelTabla,Priority.ALWAYS);page.getChildren().add(cuerpo);VBox.setVgrow(cuerpo,Priority.ALWAYS);page.getChildren().add(estadoGlobal);
        tabla.getSelectionModel().selectedItemProperty().addListener((o,an,seleccion)->{if(seleccion!=null){controller.seleccionarPorCodigo(seleccion.getCodigo());actualizarDetalle();}});
        buscar.textProperty().addListener((o,a,q)->filtrarTabla(q));bNueva.setOnAction(e->mostrarNueva());bEditar.setOnAction(e->mostrarEdicion());bEliminar.setOnAction(e->eliminarSeleccion());bDemo.setOnAction(e->cargarDemo());cambiar(page);
    }
    private VBox pagina(String titulo,String subtitulo){VBox p=new VBox(16);p.setPadding(new Insets(22,28,18,28));p.getStyleClass().add("page");VBox cab=Componentes.tarjeta();cab.getChildren().addAll(Componentes.etiqueta(titulo,"page-title"),Componentes.etiqueta(subtitulo,"text-muted"));p.getChildren().add(cab);return p;}
    private Node tarjetasEstadisticas(){EstadisticasOrdenes e=controller.servicio().estadisticas();HBox h=new HBox(14);h.getChildren().addAll(tarjetaNumero("Activas",e.activas(),"stat-blue"),tarjetaNumero("Pendientes",e.pendientes(),"stat-warning"),tarjetaNumero("En proceso",e.enProceso(),"stat-purple"),tarjetaNumero("Finalizadas",e.finalizadas(),"stat-success"));return h;}
    private Node tarjetaNumero(String texto,int numero,String estilo){VBox b=Componentes.tarjeta();b.getStyleClass().add(estilo);b.setPrefWidth(190);b.getChildren().addAll(Componentes.etiqueta(String.valueOf(numero),"stat-number"),Componentes.etiqueta(texto,"text-muted"));return b;}
    @SuppressWarnings("unchecked")
    private TableView<OrdenTrabajo> crearTabla(){TableView<OrdenTrabajo> t=new TableView<>(controller.filas());t.setPlaceholder(Componentes.etiqueta("No hay órdenes todavía.","text-muted"));t.getColumns().addAll(columna("Código",o->o.getCodigo(),90),columna("Cliente",o->o.getCliente(),155),columna("Descripción",o->o.getDescripcion(),220),columna("Técnico",o->o.getTecnicoAsignado(),130),columna("Prioridad",o->o.getPrioridad().toString(),100),columna("Estado",o->o.getEstado().toString(),115),columna("Costo estimado",o->Formato.moneda(o.getCostoEstimado()),120));t.setColumnResizePolicy(TableView.CONSTRAINED_RESIZE_POLICY_FLEX_NEXT_COLUMN);t.setPrefHeight(410);return t;}
    private TableColumn<OrdenTrabajo,String> columna(String titulo,java.util.function.Function<OrdenTrabajo,String> f,double ancho){TableColumn<OrdenTrabajo,String> c=new TableColumn<>(titulo);c.setCellValueFactory(x->new SimpleStringProperty(f.apply(x.getValue())));c.setPrefWidth(ancho);return c;}
    private Node navegacionTabla(){HBox h=new HBox(10);Button anterior=Componentes.boton("‹ Anterior","button-outline"),siguiente=Componentes.boton("Siguiente ›","button-primary"),directo=Componentes.boton("⇥ Recorrer inicio → final","button-outline"),inverso=Componentes.boton("⇤ Recorrer final → inicio","button-outline");anterior.setOnAction(e->{controller.anterior();sincronizarSeleccion();});siguiente.setOnAction(e->{controller.siguiente();sincronizarSeleccion();});directo.setOnAction(e->{controller.seleccionar(controller.servicio().getLista().getPrimero());sincronizarSeleccion();estadoGlobal.setText("Recorrido real: inicio → final.");});inverso.setOnAction(e->{controller.seleccionar(controller.servicio().getLista().getUltimo());sincronizarSeleccion();estadoGlobal.setText("Recorrido real: final → inicio.");});h.getChildren().addAll(anterior,siguiente,directo,inverso);return h;}
    private void filtrarTabla(String q){if(q==null||q.isBlank()){tabla.setItems(controller.filas());return;}var visual=FXCollections.<OrdenTrabajo>observableArrayList();String s=q.toLowerCase().trim();for(OrdenTrabajo o:controller.filas())if(o.getCodigo().toLowerCase().contains(s)||o.getCliente().toLowerCase().contains(s))visual.add(o);tabla.setItems(visual);}
    private void sincronizarSeleccion(){Nodo n=controller.seleccionado();if(n==null)return;for(OrdenTrabajo o:tabla.getItems())if(o==n.getOrden()){tabla.getSelectionModel().select(o);tabla.scrollTo(o);break;}actualizarDetalle();}
    private void actualizarDetalle(){Nodo n=controller.seleccionado();if(n==null){detalle.setText("Seleccione una orden para ver su detalle.");return;}OrdenTrabajo o=n.getOrden();detalle.setText(o.getCodigo()+"\n\nCliente\n"+o.getCliente()+"\n\nDescripción\n"+o.getDescripcion()+"\n\nTécnico\n"+o.getTecnicoAsignado()+"\n\n"+o.getPrioridad()+" · "+o.getEstado()+"\n"+Formato.moneda(o.getCostoEstimado())+"\nFecha: "+Formato.fecha(o.getFechaSolicitud()));}
    private void cargarDemo(){try{controller.servicio().cargarDemostracion();controller.refrescar();estadoGlobal.setText("Ejemplos oficiales OT-001 a OT-005 cargados.");mostrarDashboard(true);}catch(RuntimeException ex){Componentes.mensaje(Alert.AlertType.WARNING,"No se cargaron ejemplos",ex.getMessage());}}
    private void eliminarSeleccion(){Nodo n=controller.seleccionado();if(n==null){Componentes.mensaje(Alert.AlertType.INFORMATION,"Seleccione una orden","Seleccione una fila antes de eliminar.");return;}if(Componentes.confirmar("Se eliminará "+n.getOrden().getCodigo()+" de la lista doblemente enlazada.")){controller.servicio().getLista().eliminarPorCodigo(n.getOrden().getCodigo());controller.seleccionar(null);controller.refrescar();estadoGlobal.setText("Orden eliminada correctamente.");mostrarDashboard(true);}}

    private void mostrarNueva(){activo(nueva);FormularioOrden f=new FormularioOrden();VBox p=pagina("Nueva orden","Registre una nueva orden en la estructura real.");HBox body=new HBox(16);VBox formulario=Componentes.tarjeta();formulario.getChildren().addAll(Componentes.etiqueta("Información de la orden","section-title"),f.grid);VBox preview=Componentes.tarjeta();preview.setPrefWidth(320);preview.getChildren().addAll(Componentes.etiqueta("Vista previa","section-title"),f.preview);body.getChildren().addAll(formulario,preview);HBox.setHgrow(formulario,Priority.ALWAYS);p.getChildren().add(body);HBox botones=new HBox(10);Button guardar=Componentes.boton("▣ Guardar orden","button-primary"),limpiar=Componentes.boton("Limpiar","button-outline"),cancelar=Componentes.boton("Cancelar","button-outline");botones.getChildren().addAll(guardar,limpiar,cancelar);p.getChildren().add(botones);guardar.setOnAction(e->{try{OrdenTrabajo o=f.crear();TipoInsercion t=f.tipo();controller.servicio().registrar(o,t,f.posicion());controller.refrescar();estadoGlobal.setText("Orden "+o.getCodigo()+" insertada correctamente.");Componentes.mensaje(Alert.AlertType.INFORMATION,"Orden guardada","La orden se insertó en la lista doblemente enlazada.");mostrarEstructura();}catch(RuntimeException ex){Componentes.mensaje(Alert.AlertType.ERROR,"Revise la información",ex.getMessage());}});limpiar.setOnAction(e->f.limpiar());cancelar.setOnAction(e->mostrarDashboard(true));cambiar(p);}
    private final class FormularioOrden {
        final GridPane grid=new GridPane();final TextField codigo=new TextField(),cliente=new TextField(),tecnico=new TextField(),costo=new TextField();final TextArea descripcion=new TextArea();final DatePicker fecha=new DatePicker(LocalDate.now());final ComboBox<Prioridad> prioridad=new ComboBox<>();final ComboBox<EstadoOrden> estado=new ComboBox<>();final ComboBox<String> ubicacion=new ComboBox<>();final Spinner<Integer> pos=new Spinner<>(1,controller.servicio().getLista().getCantidad()+1,1);final Label preview=Componentes.etiqueta("Complete los campos obligatorios para ver la orden.","detail-text");
        FormularioOrden(){grid.setHgap(12);grid.setVgap(10);grid.setPadding(new Insets(4));descripcion.setPrefRowCount(3);prioridad.setItems(FXCollections.observableArrayList(Prioridad.values()));estado.setItems(FXCollections.observableArrayList(EstadoOrden.values()));ubicacion.setItems(FXCollections.observableArrayList("Insertar al inicio","Insertar al final","Insertar en posición específica"));ubicacion.getSelectionModel().select(1);prioridad.getSelectionModel().select(Prioridad.MEDIA);estado.getSelectionModel().select(EstadoOrden.PENDIENTE);int r=0;agregar("Código *",codigo,0,r);agregar("Cliente *",cliente,1,r++);agregar("Descripción *",descripcion,0,r++);agregar("Fecha de solicitud *",fecha,0,r);agregar("Técnico asignado *",tecnico,1,r++);agregar("Prioridad *",prioridad,0,r);agregar("Estado *",estado,1,r++);agregar("Costo estimado *",costo,0,r);agregar("Ubicación *",ubicacion,1,r++);agregar("Posición (1..n+1)",pos,0,r);grid.add(Componentes.etiqueta("Las posiciones son 1-basadas; 1 equivale al inicio.","text-muted"),1,r);codigo.textProperty().addListener((x,a,b)->actualizar());cliente.textProperty().addListener((x,a,b)->actualizar());descripcion.textProperty().addListener((x,a,b)->actualizar());tecnico.textProperty().addListener((x,a,b)->actualizar());costo.textProperty().addListener((x,a,b)->actualizar());prioridad.valueProperty().addListener((x,a,b)->actualizar());estado.valueProperty().addListener((x,a,b)->actualizar());ubicacion.valueProperty().addListener((x,a,b)->{pos.setDisable(!b.contains("posición"));actualizar();});actualizar();}
        void agregar(String l,Node c,int col,int fila){grid.add(Componentes.etiqueta(l,"field-label"),col*2,fila);grid.add(c,col*2+1,fila);GridPane.setHgrow(c,Priority.ALWAYS);}
        void actualizar(){preview.setText("Código: "+valor(codigo)+"\nCliente: "+valor(cliente)+"\n\n"+valor(descripcion)+"\n\nFecha: "+Formato.fecha(fecha.getValue())+"\nTécnico: "+valor(tecnico)+"\nPrioridad: "+prioridad.getValue()+"\nEstado: "+estado.getValue()+"\nCosto: "+valor(costo)+"\n\n"+ubicacion.getValue());}
        String valor(TextInputControl c){return c.getText().isBlank()?"—":c.getText();}
        OrdenTrabajo crear(){return new OrdenTrabajo(codigo.getText(),cliente.getText(),descripcion.getText(),fecha.getValue(),tecnico.getText(),prioridad.getValue(),estado.getValue(),new BigDecimal(costo.getText().trim().replace(",",".")));}
        TipoInsercion tipo(){return ubicacion.getValue().contains("inicio")?TipoInsercion.INICIO:ubicacion.getValue().contains("final")?TipoInsercion.FINAL:TipoInsercion.POSICION;}
        int posicion(){return pos.getValue();}
        void limpiar(){codigo.clear();cliente.clear();descripcion.clear();tecnico.clear();costo.clear();fecha.setValue(LocalDate.now());prioridad.setValue(Prioridad.MEDIA);estado.setValue(EstadoOrden.PENDIENTE);ubicacion.getSelectionModel().select(1);pos.getValueFactory().setValue(1);actualizar();}
    }

    private void mostrarEdicion(){
        activo(editar);VBox p=pagina("Editar orden","Localice una orden y modifique únicamente sus campos autorizados.");
        TextField buscar=new TextField();buscar.setPromptText("Código de la orden, por ejemplo OT-001");Button consultar=Componentes.boton("Buscar","button-primary");HBox barra=new HBox(10,Componentes.etiqueta("Buscar por código", "field-label"),buscar,consultar);HBox.setHgrow(buscar,Priority.ALWAYS);p.getChildren().add(barra);
        GridPane g=new GridPane();g.setHgap(12);g.setVgap(10);VBox form=Componentes.tarjeta();form.getChildren().add(Componentes.etiqueta("Información de la orden","section-title"));
        TextField codigo=new TextField(),cliente=new TextField(),tecnico=new TextField(),costo=new TextField();TextArea descripcion=new TextArea();DatePicker fecha=new DatePicker();ComboBox<Prioridad> prioridad=new ComboBox<>(FXCollections.observableArrayList(Prioridad.values()));ComboBox<EstadoOrden> estado=new ComboBox<>(FXCollections.observableArrayList(EstadoOrden.values()));codigo.setEditable(false);cliente.setEditable(false);fecha.setDisable(true);descripcion.setPrefRowCount(3);int r=0;editarCampo(g,"Código (inmutable)",codigo,0,r);editarCampo(g,"Cliente (no modificable)",cliente,1,r++);editarCampo(g,"Descripción *",descripcion,0,r++);editarCampo(g,"Fecha de solicitud",fecha,0,r);editarCampo(g,"Técnico asignado *",tecnico,1,r++);editarCampo(g,"Prioridad *",prioridad,0,r);editarCampo(g,"Estado *",estado,1,r++);editarCampo(g,"Costo estimado *",costo,0,r++);form.getChildren().add(g);p.getChildren().add(form);
        HBox acciones=new HBox(10);Button guardar=Componentes.boton("▣ Guardar cambios","button-primary"),restablecer=Componentes.boton("Restablecer","button-outline"),eliminar=Componentes.boton("⌫ Eliminar orden","button-danger");acciones.getChildren().addAll(guardar,restablecer,eliminar);p.getChildren().add(acciones);
        Runnable cargar=()->{OrdenTrabajo o=controller.servicio().getLista().buscarPorCodigo(buscar.getText());if(o==null){Componentes.mensaje(Alert.AlertType.INFORMATION,"Sin resultados","No existe una orden con ese código.");return;}codigo.setText(o.getCodigo());cliente.setText(o.getCliente());descripcion.setText(o.getDescripcion());fecha.setValue(o.getFechaSolicitud());tecnico.setText(o.getTecnicoAsignado());prioridad.setValue(o.getPrioridad());estado.setValue(o.getEstado());costo.setText(o.getCostoEstimado().toPlainString());controller.seleccionarPorCodigo(o.getCodigo());};
        consultar.setOnAction(e->cargar.run());buscar.setOnAction(e->cargar.run());guardar.setOnAction(e->{try{if(codigo.getText().isBlank())throw new IllegalArgumentException("Primero busque una orden.");controller.servicio().modificar(codigo.getText(),descripcion.getText(),tecnico.getText(),prioridad.getValue(),estado.getValue(),new BigDecimal(costo.getText().trim().replace(",",".")));controller.refrescar();estadoGlobal.setText("Cambios guardados en "+codigo.getText()+".");Componentes.mensaje(Alert.AlertType.INFORMATION,"Cambios guardados","La misma orden de la lista fue actualizada.");}catch(RuntimeException ex){Componentes.mensaje(Alert.AlertType.ERROR,"No se guardaron los cambios",ex.getMessage());}});restablecer.setOnAction(e->cargar.run());eliminar.setOnAction(e->{if(codigo.getText().isBlank())return;if(Componentes.confirmar("Se eliminará "+codigo.getText()+".")){controller.servicio().getLista().eliminarPorCodigo(codigo.getText());controller.refrescar();estadoGlobal.setText("Orden eliminada.");mostrarDashboard(true);}});cambiar(p);
    }
    private void editarCampo(GridPane g,String etiqueta,Node campo,int columna,int fila){g.add(Componentes.etiqueta(etiqueta,"field-label"),columna*2,fila);g.add(campo,columna*2+1,fila);GridPane.setHgrow(campo,Priority.ALWAYS);}

    private void mostrarEstructura(){
        activo(estructura);VBox p=pagina("Visualización de la estructura de datos","Representación gráfica de los nodos y enlaces reales de ListaDoble.");
        ListaDoble lista=controller.servicio().getLista();if(controller.seleccionado()==null&&!lista.estaVacia())controller.seleccionar(lista.getPrimero());
        HBox cadena=new HBox(9);cadena.setAlignment(Pos.CENTER_LEFT);cadena.getChildren().add(nulo());for(Nodo n:lista.nodosAdelante()){cadena.getChildren().add(flechas());cadena.getChildren().add(tarjetaNodo(n));}if(!lista.estaVacia())cadena.getChildren().add(flechas());cadena.getChildren().add(nulo());ScrollPane scroll=new ScrollPane(cadena);scroll.setFitToHeight(true);scroll.setHbarPolicy(ScrollPane.ScrollBarPolicy.AS_NEEDED);scroll.getStyleClass().add("structure-scroll");VBox visual=Componentes.tarjeta();visual.getChildren().addAll(Componentes.etiqueta("Lista doblemente enlazada · "+lista.getCantidad()+" nodo(s)","section-title"),scroll);p.getChildren().add(visual);
        HBox controles=new HBox(10);Button anterior=Componentes.boton("‹ Anterior","button-outline"),siguiente=Componentes.boton("Siguiente ›","button-primary"),directo=Componentes.boton("Recorrer inicio → final","button-outline"),inverso=Componentes.boton("Recorrer final → inicio","button-outline"),integridad=Componentes.boton("✓ Verificar integridad","button-outline");controles.getChildren().addAll(anterior,siguiente,directo,inverso,integridad);p.getChildren().add(controles);
        VBox info=Componentes.tarjeta();Nodo n=controller.seleccionado();ResultadoIntegridad ri=lista.verificarIntegridad();String datos=n==null?"La lista no tiene nodos.":datosNodo(n,lista);Label detalleNodo=Componentes.etiqueta(datos,"detail-text");Label estado=Componentes.etiqueta((ri.valida()?"✓ ":"⚠ ")+ri.detalle(),ri.valida()?"valid":"invalid");info.getChildren().addAll(Componentes.etiqueta("Nodo seleccionado y estado de la estructura","section-title"),detalleNodo,estado);p.getChildren().add(info);
        anterior.setOnAction(e->{controller.anterior();mostrarEstructura();});siguiente.setOnAction(e->{controller.siguiente();mostrarEstructura();});directo.setOnAction(e->{controller.seleccionar(lista.getPrimero());estadoGlobal.setText("Recorrido real iniciado desde PRIMERO.");mostrarEstructura();});inverso.setOnAction(e->{controller.seleccionar(lista.getUltimo());estadoGlobal.setText("Recorrido real iniciado desde ÚLTIMO.");mostrarEstructura();});integridad.setOnAction(e->{ResultadoIntegridad x=lista.verificarIntegridad();Componentes.mensaje(x.valida()?Alert.AlertType.INFORMATION:Alert.AlertType.ERROR,"Verificación de integridad",x.detalle());mostrarEstructura();});cambiar(p);
    }
    private Node nulo(){Label l=Componentes.etiqueta("NULL","null-node");l.setMinWidth(70);l.setAlignment(Pos.CENTER);return l;}
    private Node flechas(){Label l=Componentes.etiqueta("⇄","link-arrow");l.setMinWidth(34);l.setAlignment(Pos.CENTER);return l;}
    private Node tarjetaNodo(Nodo nodo){OrdenTrabajo o=nodo.getOrden();VBox b=Componentes.tarjeta();b.getStyleClass().add("node-card");if(nodo==controller.seleccionado())b.getStyleClass().add("node-selected");if(nodo==controller.servicio().getLista().getPrimero())b.getStyleClass().add("node-first");if(nodo==controller.servicio().getLista().getUltimo())b.getStyleClass().add("node-last");b.setPrefWidth(165);Label marca=Componentes.etiqueta(nodo==controller.servicio().getLista().getPrimero()?"PRIMERO":nodo==controller.servicio().getLista().getUltimo()?"ÚLTIMO":"NODO","node-mark");b.getChildren().addAll(marca,Componentes.etiqueta(o.getCodigo(),"node-code"),Componentes.etiqueta(o.getCliente(),"text-muted"),Componentes.etiqueta(o.getEstado().toString(),"badge"),Componentes.etiqueta("Pos. "+controller.servicio().getLista().posicionDe(nodo),"text-muted"));b.setOnMouseClicked(e->{controller.seleccionar(nodo);mostrarEstructura();});return b;}
    private String datosNodo(Nodo n,ListaDoble l){OrdenTrabajo o=n.getOrden();String ant=n.getAnterior()==null?"NULL":n.getAnterior().getOrden().getCodigo(),sig=n.getSiguiente()==null?"NULL":n.getSiguiente().getOrden().getCodigo();return "Código: "+o.getCodigo()+" · Posición "+l.posicionDe(n)+" de "+l.getCantidad()+"\nCliente: "+o.getCliente()+"\nDescripción: "+o.getDescripcion()+"\nEstado: "+o.getEstado()+" · "+o.getPrioridad()+"\nAnterior: "+ant+"\nSiguiente: "+sig;}

    private void mostrarPruebas(){
        activo(pruebas);VBox p=pagina("Laboratorio de pruebas e integridad","Los casos se ejecutan sobre instancias aisladas de ListaDoble.");int aprobadas=0,fallidas=0,pendientes=0;for(CasoPruebaResultado r:laboratorio.getResultados())switch(r.getEstado()){case APROBADA->aprobadas++;case FALLIDA->fallidas++;case PENDIENTE->pendientes++;}HBox resumen=new HBox(14,tarjetaNumero("Aprobadas",aprobadas,"stat-success"),tarjetaNumero("Fallidas",fallidas,"stat-danger"),tarjetaNumero("Pendientes",pendientes,"stat-warning"));p.getChildren().add(resumen);
        TableView<CasoPruebaResultado> t=new TableView<>(laboratorio.getResultados());t.getColumns().addAll(colCaso("Caso",CasoPruebaResultado::getId,75),colCaso("Operación",CasoPruebaResultado::getDescripcion,185),colCaso("Resultado esperado",CasoPruebaResultado::getEsperado,210),colCaso("Obtenido",CasoPruebaResultado::getObtenido,190),colCaso("Estado",r->r.getEstado().toString(),100));t.setPrefHeight(365);t.setColumnResizePolicy(TableView.CONSTRAINED_RESIZE_POLICY_FLEX_NEXT_COLUMN);VBox caja=Componentes.tarjeta();caja.getChildren().addAll(Componentes.etiqueta("Casos obligatorios CP-01 a CP-15","section-title"),t);p.getChildren().add(caja);VBox.setVgrow(caja,Priority.ALWAYS);
        HBox acciones=new HBox(10);Button todas=Componentes.boton("▶ Ejecutar todas","button-primary"),seleccion=Componentes.boton("Ejecutar selección","button-outline"),limpiar=Componentes.boton("Limpiar resultados","button-danger"),exportar=Componentes.boton("⇩ Exportar evidencias","button-outline"),verificar=Componentes.boton("Verificar lista actual","button-outline");acciones.getChildren().addAll(todas,seleccion,limpiar,exportar,verificar);p.getChildren().add(acciones);Label consola=Componentes.etiqueta(resumenConsola(),"console");p.getChildren().add(consola);todas.setOnAction(e->{laboratorio.ejecutarTodas();mostrarPruebas();});seleccion.setOnAction(e->{CasoPruebaResultado r=t.getSelectionModel().getSelectedItem();if(r==null)Componentes.mensaje(Alert.AlertType.INFORMATION,"Seleccione un caso","Seleccione una fila de prueba.");else{laboratorio.ejecutar(r);mostrarPruebas();}});limpiar.setOnAction(e->{laboratorio.limpiar();mostrarPruebas();});exportar.setOnAction(e->exportarEvidencias(p.getScene()==null?null:p.getScene().getWindow()));verificar.setOnAction(e->{ResultadoIntegridad r=controller.servicio().getLista().verificarIntegridad();Componentes.mensaje(r.valida()?Alert.AlertType.INFORMATION:Alert.AlertType.ERROR,"Integridad de la lista principal",r.detalle());});cambiar(p);
    }
    private TableColumn<CasoPruebaResultado,String> colCaso(String titulo,java.util.function.Function<CasoPruebaResultado,String> f,double ancho){TableColumn<CasoPruebaResultado,String> c=new TableColumn<>(titulo);c.setCellValueFactory(x->new SimpleStringProperty(f.apply(x.getValue())));c.setPrefWidth(ancho);return c;}
    private String resumenConsola(){StringBuilder s=new StringBuilder("Consola de resultados\n");for(CasoPruebaResultado r:laboratorio.getResultados())s.append(r.getId()).append(" · ").append(r.getEstado()).append(" — ").append(r.getDetalle()).append('\n');return s.toString();}
    private void exportarEvidencias(Window ventana){FileChooser fc=new FileChooser();fc.setTitle("Exportar evidencias");fc.setInitialFileName("evidencias-tecnomant.txt");fc.getExtensionFilters().add(new FileChooser.ExtensionFilter("Texto", "*.txt"));File archivo=fc.showSaveDialog(ventana);if(archivo==null)return;try(PrintWriter out=new PrintWriter(archivo)){out.println("TecnoMant Solutions - Evidencias CP-01 a CP-15");out.println();for(CasoPruebaResultado r:laboratorio.getResultados())out.println(r.getId()+" | "+r.getDescripcion()+" | Esperado: "+r.getEsperado()+" | Obtenido: "+r.getObtenido()+" | Estado: "+r.getEstado()+" | "+r.getDetalle());Componentes.mensaje(Alert.AlertType.INFORMATION,"Evidencia exportada","Archivo creado correctamente.");}catch(Exception e){Componentes.mensaje(Alert.AlertType.ERROR,"No se pudo exportar",e.getMessage());}}
